public class Main {
    public static void main(String[] args) {
        int[] readings = {5, 8, 12};
        int high = 0;
        for (int reading : readings) {
            if (reading >= 8) {
                high++;
            }
        }
        System.out.println(high);
    }
}

interface Described {
    String label();
}

public class Main implements Described {
    private final String name;

    Main(String name) {
        this.name = name;
    }

    @Override
    public String label() {
        return "Item: " + name;
    }

    public static void main(String[] args) {
        Described entry = new Main("Lamp");
        System.out.println(entry.label());
    }
}

import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        var names = List.of("Ion", "Ada", "Ion");
        Map<String, Integer> counts = new HashMap<>();
        for (String name : names) {
            counts.merge(name, 1, Integer::sum);
        }
        System.out.println(counts.getOrDefault("Ion", 0));
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.StringReader;

public class Main {
    public static void main(String[] args) {
        try (var input = new BufferedReader(new StringReader("42\n"))) {
            System.out.println(Integer.parseInt(input.readLine()));
        } catch (IOException | NumberFormatException error) {
            System.err.println(error.getMessage());
        }
    }
}

import java.util.List;

public class Main {
    public static void main(String[] args) {
        var labels = List.of("ion", "app", "java");
        var lengths = labels.stream()
            .filter(label -> label.length() >= 3)
            .map(String::length)
            .toList();
        System.out.println(lengths);
    }
}

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;

public class Main {
    public static void main(String[] args) throws Exception {
        Path file = Files.createTempFile("ion-study-", ".txt");
        try {
            LocalDate day = LocalDate.of(2026, 11, 9);
            Files.writeString(file, day.plusDays(7).toString());
            System.out.println(LocalDate.parse(Files.readString(file)));
        } finally {
            Files.deleteIfExists(file);
        }
    }
}
